// userApi.js (수정 완료)

import api from "./axiosConfig";

/**
 * 로그인, 회원가입, 현재 사용자 정보 가져오기 등
 * 🚨 수정: 엔드포인트를 '/auth'에서 백엔드 라우트 '/api/users'에 맞춰 수정합니다.
 */

export const register = (payload) => api.post("/users/register", payload);
export const login = (payload) => api.post("/users/login", payload);
export const getMe = () => api.get("/users/profile"); // 백엔드 라우트와 일치시키기 위해 /users/profile로 수정

export const logout = () => {
  localStorage.removeItem("token");
  return Promise.resolve();
};

const userApi = { register, login, getMe, logout };
export default userApi;
